// Strip ranges into LED_POS[]. kind: 0=helix(retired), 1=canopy, 2=root, 3=strap.
// axn: axial raster resolution for wrapped/folded strips (0 = index space).
// A renderer rasterizing a root at axn pixels and sampling by each LED's
// axial position makes effects travel DOWN the pole, whatever the wire path.
struct HcStrip { uint16_t start, count; uint8_t kind; uint16_t axn; };
